   153	fn try_acquire_token(
   154	    buckets: &DashMap<String, BucketEntry>,
   155	    peer_ip: &str,
   156	    rate_per_sec: f64,
   157	    burst: f64,
   158	) -> bool {
   159	    let key = peer_ip.to_string();
   160	    buckets
   161	        .entry(key.clone())
   162	        .or_insert_with(|| {
   163	            (
   164	                std::sync::Mutex::new((burst, Instant::now())),
   165	                rate_per_sec,
   166	                burst,
   167	            )
   168	        });
   169	    let entry = buckets.get(&key).unwrap();
   170	    let mut guard = entry.0.lock().unwrap();
   171	    let (tokens, last) = *guard;
   172	    let now = Instant::now();
   173	    let elapsed = now.duration_since(last).as_secs_f64();
   174	    let refill = rate_per_sec * elapsed;
   175	    let tokens = (tokens + refill).min(burst);
   176	    if tokens >= 1.0 {
   177	        *guard = (tokens - 1.0, now);
   178	        true
   179	    } else {
   180	        false
   181	    }
   182	}
