   204	/// Remove stale entries from token buckets and zero-count session counters.
   205	/// Call periodically (e.g. every 60s) to prevent unbounded memory growth.
   206	pub fn cleanup_stale_entries(max_idle_secs: f64) {
   207	    let now = Instant::now();
   208	    STREAM_BUCKETS.retain(|_, v| {
   209	        let guard = v.0.lock().unwrap();
   210	        now.duration_since(guard.1).as_secs_f64() < max_idle_secs
   211	    });
   212	    DGRAM_BUCKETS.retain(|_, v| {
   213	        let guard = v.0.lock().unwrap();
   214	        now.duration_since(guard.1).as_secs_f64() < max_idle_secs
   215	    });
   216	    PER_IP_SESSIONS.retain(|_, v| v.load(Ordering::Relaxed) > 0);
   217	    PER_PREFIX_SESSIONS.retain(|_, v| v.load(Ordering::Relaxed) > 0);
   218	}

