   103	/// Spawn a background task that batches events from a channel and delivers
   104	/// them to a ThreadsafeFunction in groups (max_batch items or every flush_ms).
   105	pub(crate) fn spawn_event_batcher<T: Send + 'static>(
   106	    tsfn: napi::threadsafe_function::ThreadsafeFunction<
   107	        Vec<T>,
   108	        napi::threadsafe_function::ErrorStrategy::Fatal,
   109	    >,
   110	    max_batch: usize,
   111	    flush_ms: u64,
   112	) -> tokio::sync::mpsc::Sender<T> {
   113	    let (tx, mut rx) = tokio::sync::mpsc::channel::<T>(512);
   114	    RUNTIME.spawn(async move {
   115	        let mut batch = Vec::with_capacity(max_batch);
   116	        loop {
   117	            if batch.is_empty() {
   118	                match rx.recv().await {
   119	                    Some(e) => batch.push(e),
   120	                    None => break,
   121	                }
   122	            }
   123	            let deadline = tokio::time::Instant::now()
   124	                + tokio::time::Duration::from_millis(flush_ms);
   125	            loop {
   126	                if batch.len() >= max_batch {
   127	                    break;
   128	                }
   129	                tokio::select! {
   130	                    event = rx.recv() => {
   131	                        match event {
   132	                            Some(e) => batch.push(e),
   133	                            None => {
   134	                                tsfn.call(
   135	                                    std::mem::take(&mut batch),
   136	                                    napi::threadsafe_function::ThreadsafeFunctionCallMode::NonBlocking,
   137	                                );
   138	                                return;
   139	                            }
   140	                        }
   141	                    }
   142	                    _ = tokio::time::sleep_until(deadline) => break,
   143	                }
   144	            }
   145	            if !batch.is_empty() {
   146	                tsfn.call(
   147	                    std::mem::take(&mut batch),
   148	                    napi::threadsafe_function::ThreadsafeFunctionCallMode::NonBlocking,
   149	                );
   150	                batch = Vec::with_capacity(max_batch);
   151	            }
   152	        }
   153	        if !batch.is_empty() {
   154	            tsfn.call(
   155	                batch,
   156	                napi::threadsafe_function::ThreadsafeFunctionCallMode::NonBlocking,
   157	            );
   158	        }
   159	    });
