     9	/// Run a closure, catching panics and converting to `Err(E_INTERNAL: ...)`.
    10	/// Logs the panic for debugging.
    11	pub fn catch_panic<R, F>(f: F) -> Result<R>
    12	where
    13	    F: FnOnce() -> Result<R> + std::panic::UnwindSafe,
    14	{
    15	    match panic::catch_unwind(AssertUnwindSafe(f)) {
    16	        Ok(inner) => inner,
    17	        Err(panic_any) => {
    18	            let msg = panic_any
    19	                .downcast_ref::<&str>()
    20	                .map(|s| (*s).to_string())
