    23	            eprintln!("webtransport-native: panic contained: {}", msg);
    24	            Err(napi::Error::from_reason(format!(
    25	                "{}{}",
    26	                E_INTERNAL_PREFIX, msg
    27	            )))
    28	        }
    29	    }
