#[napi]
pub struct ClientBidiStreamHandle {
    read_rx: Arc<TokioMutex<mpsc::Receiver<Vec<u8>>>>,
    write_tx: Option<mpsc::Sender<StreamCmd>>,
    stop_tx: std::sync::Mutex<Option<oneshot::Sender<u32>>>,
